import*as THREE from'three';import{materials}from'../../core/index.js';import{addCadParts}from'../../modeling/cad.js';import{mesh,slab,screw}from'../../modeling/parts.js';import data from'./geometry-data.js';import{grove,terminal}from'./connectors.js';import{addStickers}from'./stickers.js';
const tau=Math.PI*2;function hole(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,tau,false);s.holes.push(p);}function extrude(parent,s,depth,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:48}),m,p,n);}
function board(host){
 const s=new THREE.Shape();s.moveTo(-10.4,-24);s.lineTo(-8.8,-26);s.lineTo(-5.5,-26);s.lineTo(-5.5,-20.2);s.lineTo(5.5,-20.2);s.lineTo(5.5,-26);s.lineTo(8.8,-26);s.lineTo(10.4,-24);s.lineTo(10.4,-19.6);s.lineTo(8,-19.6);s.absarc(8,-16,3.6,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.4,-12.4);s.lineTo(10.4,24.3);s.lineTo(8.5,26.3);s.lineTo(-8.5,26.3);s.lineTo(-10.4,24.3);s.lineTo(-10.4,-12.4);s.lineTo(-8,-12.4);s.absarc(-8,-16,3.6,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.4,-19.6);s.closePath();hole(s,0,-16,2.1);
 const pcb=extrude(host.body,s,.8,[0,0,-2.5],materials.plastic(0x186d45,{roughness:.87}),'INA226-10A fixed PCB with genuine mounting reliefs and retaining bore');pcb.userData.role='physical-pcb';
 const metal=materials.metal(0xb6bba9,{roughness:.49}),dark=materials.plastic(0x20231f,{roughness:.85}),ceramic=materials.plastic(0xb3a57d,{roughness:.82}),packages=[];
 // Own U200 schematic identifies the packages. Hidden placement is reconstructed,
 // never a measured isolation barrier or a manufacturing PCB/BOM layout.
 const ic=(x,y,w,h,z,depth,n,leads,pitch=.65)=>{const body=slab(host.body,w,h,depth,.1,[x,y,z],dark,[],.02);body.name='INA226-10A '+n;packages.push(body);for(const sign of[-1,1]){const count=Array.isArray(leads)?leads[sign===-1?0:1]:leads;for(let i=0;i<count;i++)mesh(host.body,new THREE.BoxGeometry(.8,.25,.16),metal,[x+sign*(w/2+.26),y+(i-(count-1)/2)*pitch,-1.45],n+' physical lead');}return body;};
 const monitor=ic(3.9,11.6,3,3,-1.55,1.0,'U2 INA226AIDGSR MSOP10 body',5,.5),isolator=ic(2.3,1.5,3.9,5,-1.55,1.45,'U1 CA-IS3020-family SOIC8 isolation footprint',4,1.27);
 const converter=slab(host.body,7.5,10.3,2.5,.18,[-4.8,-5.1,-1.55],dark,[],.02);converter.name='INA226-10A M1 B0505ST16-W5 isolated supply physical body';packages.push(converter);const converterLeads=[];for(const side of[-1,1])for(let i=0;i<8;i++)converterLeads.push(mesh(host.body,new THREE.BoxGeometry(1.4,.39,.18),metal,[-4.8+side*4.45,-5.1+(i-3.5)*1.27,-1.4],'INA226-10A M1 physical package lead'));
 const regulators=[ic(-6.4,8.5,1.7,2.9,-1.55,.95,'U3 XC6228D332VR-G measurement-side SOT25 body',[3,2],.65),ic(6.8,-7.4,1.7,2.9,-1.55,.95,'U4 XC6228D332VR-G host-side SOT25 body',[3,2],.65)];
 const shunt=mesh(host.body,new THREE.BoxGeometry(3.2,6.4,.55),dark,[4.9,20.4,-1.2],'INA226-10A R3 5mΩ current shunt fixed body');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(3.2,1.15,.65),metal,[4.9,20.4+sign*2.7,-1.2],'INA226-10A shunt metal termination');
 const fuse=mesh(host.body,new THREE.BoxGeometry(3.2,1.6,.75),materials.plastic(0xc4b96e,{roughness:.83}),[-4.7,21.1,-1.175],'INA226-10A FUSE1 BSMD1206C-2120T fixed body');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.42,1.6,.8),metal,[-4.7+sign*1.42,21.1,-1.2],'INA226-10A FUSE1 metal termination');
 const passives=[];for(const[i,x,y]of[[1,-8.2,16.5],[2,-8.2,13.8],[3,-6.3,4.8],[4,-6.3,2.4],[5,-3.8,3.6],[6,7.8,6.1],[7,7.8,8.5],[8,7.8,11],[9,4.1,-10.8],[10,6.5,-10.8],[11,-8.4,-1.4],[12,-8.4,-4],[13,2.1,15.3],[14,-.5,15.3],[15,1.7,7.8],[16,4.2,7.8],[17,2.7,-5],[18,6.8,-3.3]]){passives.push(mesh(host.body,new THREE.BoxGeometry(1.6,.9,.7),i%3?ceramic:dark,[x,y,-1.3],'INA226-10A fixed resistor capacitor diode package '+i));for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.28,.9,.72),metal,[x+sign*.66,y,-1.3],'INA226-10A passive solder end');}
 const inputInductor=mesh(host.body,new THREE.BoxGeometry(3.2,2.5,1.4),dark,[-3.3,-11,-1],'INA226-10A L2 6.8uH fixed inductor package');const returnBead=mesh(host.body,new THREE.BoxGeometry(1.6,.8,.7),dark,[-.1,11.8,-1.3],'INA226-10A L1 ferrite bead fixed body');
 const ledBase=mesh(host.body,new THREE.BoxGeometry(1.6,.85,.45),materials.plastic(0xe4e5d8,{roughness:.72}),[8.3,-20.9,-1.5],'INA226-10A concealed D2 BLUE0603 LED substrate'),hiddenLed=mesh(host.body,new THREE.BoxGeometry(.9,.65,.16),materials.plastic(0x3e6eab,{roughness:.45}),[8.3,-20.9,-1.195],'INA226-10A concealed blue D2 resin,non-emissive');for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.2,.85,.35),metal,[8.3+sign*.7,-20.9,-1.57],'INA226-10A concealed D2 solder end');
 const rearPads=[];for(const x of[-9.45,9.45])rearPads.push(mesh(host.body,new THREE.BoxGeometry(1.7,3.5,.035),materials.metal(0xb59b4b,{roughness:.5}),[x,21.6,-2.518],'INA226-10A fixed PCB copper edge pad visible through native retaining slot'));
 return{pcb,monitor,isolator,converter,converterLeads,regulators,fuse,shunt,inputInductor,returnBead,packages,passives,ledBase,hiddenLed,rearPads};
}
export function buildINA22610A(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe9eae5,{roughness:.78})}),pcb=board(host),input=grove(host),output=terminal(host),fixing=screw(host.body,[0,-16,-3.01],'back',1.55);fixing.name='INA226-10A fixed recessed rear hex screw';fixing.traverse(o=>{if(o.isMesh)o.name='INA226-10A fixed hex retaining screw face';});mesh(host.body,new THREE.CylinderGeometry(.65,.65,4.1,32).rotateX(Math.PI/2),materials.metal(0x9ca093),[0,-16,-.9],'INA226-10A concealed fixed screw shank');const frontCarrier=slab(host.body,15.8,26.9,.045,.9,[0,2.75,3.805],materials.plastic(0xd9dadb,{roughness:.86}),[],.005);frontCarrier.name='INA226-10A physical front adhesive label substrate over native printed recess';const backCarrier=slab(host.body,16,36,.045,.02,[0,6,-3.85],materials.plastic(0xd9dadb,{roughness:.86}),[],.005);backCarrier.name='INA226-10A physical rear adhesive label substrate over native printed recess';host.ina22610aAssembly={parts,pcb,input,output,fixing,frontCarrier,backCarrier};host.unitStickers=addStickers(host);}
